CREATE TABLE users_customuser (id INT PRIMARY KEY, email VARCHAR(255), username VARCHAR(255), nickname VARCHAR(255), password VARCHAR(255), is_active BOOLEAN, is_staff BOOLEAN, is_superuser BOOLEAN, icon VARCHAR(255), socialIcon VARCHAR(255), url VARCHAR(255), date_joined DATETIME, last_login DATETIME);
CREATE TABLE articles_markermodel (markerId INT PRIMARY KEY, latitude DOUBLE, longitude DOUBLE, park VARCHAR(2));
CREATE TABLE articles_articlemodel (postId INT PRIMARY KEY, author_id INT, marker_id INT, title VARCHAR(255), description TEXT, category INT, image VARCHAR(255), isDraft BOOLEAN, createdAt DATETIME, updatedAt DATETIME);
CREATE TABLE articles_likemodel (likeId INT PRIMARY KEY, user_id INT, article_id INT);
CREATE TABLE articles_goodmodel (goodId INT PRIMARY KEY, ipAddress VARCHAR(255), article_id INT);
CREATE TABLE special_map_specialmapmodel (specialMapId INT PRIMARY KEY, author_id INT, title VARCHAR(255), thumbnail VARCHAR(255), isPublic BOOLEAN, description TEXT, selectablePark VARCHAR(8), minLatitude DOUBLE, maxLatitude DOUBLE, minLongitude DOUBLE, maxLongitude DOUBLE, createdAt DATETIME);
CREATE TABLE special_map_specialmapmarkermodel (specialMapMarkerId INT PRIMARY KEY, specialMap_id INT, latitude DOUBLE, longitude DOUBLE, park VARCHAR(2), image VARCHAR(255), description TEXT, variant VARCHAR(20));
CREATE TABLE socialaccount_socialaccount (user_id INT, uid VARCHAR(255), provider VARCHAR(32));
